#include <vector>
#include <algorithm>
#include <numeric>

/*
 * Given a vector of positive integers representing stick lengths,
 * you may increase the length of any sticks by any positive integer amounts.
 * Return the minimum total amount of length that must be added so that
 * the largest stick is strictly less than the sum of all other sticks.
 * If the condition already holds, return 0.
 */
long long minAdditionalLength(const std::vector<long long>& lengths) {
    if (lengths.empty()) return 0; // edge case, though input typically non-empty

    long long maxLen = *std::max_element(lengths.begin(), lengths.end());
    long long totalSum = std::accumulate(lengths.begin(), lengths.end(), 0LL);

    // Condition: maxLen < totalSum - maxLen  =>  2*maxLen < totalSum
    long long deficit = 2 * maxLen - totalSum;
    if (deficit < 0) return 0;

    // Need to increase the sum of the other sticks by at least deficit+1
    return deficit + 1;
}

#include <cassert>
#include <vector>

// include the solution function here (copy above)

int main() {
    // Already satisfies condition
    assert(minAdditionalLength({1, 2, 3}) == 0); // 3 < 1+2
    assert(minAdditionalLength({5, 5, 5}) == 0); // 5 < 10

    // Single stick
    assert(minAdditionalLength({5}) == 6); // need to increase others by 6: 2*5-5+1=6

    // Two sticks
    assert(minAdditionalLength({3, 4}) == 2); // 2*4-7+1=2
    assert(minAdditionalLength({2, 2}) == 1); // 2*2-4+1=1

    // Larger example
    assert(minAdditionalLength({1, 1, 10}) == 9); // 2*10-12+1=9

    // Duplicate values
    assert(minAdditionalLength({10, 10, 10}) == 0); // already okay

    // Large numbers
    assert(minAdditionalLength({1000000000LL}) == 1000000001LL); // 2e9-1e9+1

    // Empty vector edge case (though not typical)
    assert(minAdditionalLength({}) == 0);

    return 0;
}
